1	/**
2	 * Spline water ribbon — the traversable stream Benny rides from the Drum A drain to the towel.
3	 *
4	 * Geometry: rows every `ds` along the master course, columns across `widthAt(s)`; a slightly
5	 * concave trough with raised frothy edges plus a short skirt under each edge (thickness).
6	 * Shader: electric-cyan core with meandering hot-pink flow bands, advected white streaks and
7	 * sparkles (two-phase flow-map advection so per-stage speeds never shear), Fresnel/haze
8	 * reflection, specular glints, cellular soap-foam fringe, Benny ripple rings + V-wake, the five
9	 * glowing chevrons on the 04 slide, a dithered hand-over to the whirlpool surface in 03 and a
10	 * drain-away for the 11 outro.
11	 */
12	import * as THREE from 'three';
13	import type { Course, StageId } from '../world/course';
14	import { FRAG_FX_GLSL, FRAG_TAIL, NOISE_GLSL, PALETTE, withFog } from './glsl';
15	
16	/** wave amplitude per stage (units); blended across boundaries */
17	const AMP: Partial<Record<StageId, number>> = {
18	  '02': 0.06, '03': 0.08, '04': 0.03, '05': 0.1, '06': 0.12, '07': 0.1, '08': 0.1, '09': 0.16, '10': 0.08, '11': 0.05,
19	};
20	export const EDGE_LIFT = 0.28;
21	
22	/**
23	 * Per-stage colour-band layout (blended across stage boundaries, baked into `aStyle`):
24	 *  x gate: 1 = pink bands taper off and part around Benny so the water at and behind him is pure
25	 *          cyan (ref 05: rows y=1200/1400 are 0% pink); 0 = bands run right past him (refs 04/06/07
26	 *          keep pink at the sides near the camera)
27	 *  y off:  band-centre offset from the meandering core centre, fraction of the half width
28	 *  z wid:  band half width, fraction of the half width
29	 * Between the two bands is the electric-cyan core; outside them more cyan, then the foam lace.
30	 */
31	type Style = [number, number, number, number];
32	/*  w free: weight of the shader's own drifting channel meander (meander() in FRAG). 0 in 05, where the
33	 *          course itself winds (S05/meander05 in course.ts) and the core is pinned to the route (see
34	 *          coreLateral) so the coins on the route stay on the cyan core. 1 elsewhere (04/06/07 unchanged).
35	 * 05 layout from ref 05 at the live 05 camera (y=600 ≈ 36 px/u, y=700 ≈ 63, y=800 ≈ 93): in the mid/far
36	 * field each pink band is ≈20 % of the water width, the cyan core ≈45 %, a thin outer cyan strip ≈7 %
37	 * → band centre 0.62 hw, half width 0.19 hw. Toward Benny the bands taper to half width (gate, FRAG),
38	 * which gives the ref's ≈100–130 px bands at y=800 and a pure-cyan near field. */
39	const BAND_STYLE: Partial<Record<StageId, Style>> = {
40	  '04': [0, 0.6, 0.19, 1],
41	  '05': [1, 0.62, 0.19, 0],
42	  '06': [0.4, 0.48, 0.1, 1],
43	  '07': [0, 0.52, 0.13, 1],
44	};
45	const BAND_DEFAULT: Style = [0, 0.5, 0.12, 1];
46	
47	function bandStyleAt(course: Course, s: number): Style {
48	  const o: Style = [0, 0, 0, 0];
49	  let w = 0;
50	  for (const st of course.stages) {
51	    const a = smooth(st.s0 - 5, st.s0 + 5, s) * (1 - smooth(st.s1 - 5, st.s1 + 5, s));
52	    if (a <= 0) continue;
53	    const v = BAND_STYLE[st.id] ?? BAND_DEFAULT;
54	    for (let i = 0; i < 4; i++) o[i] += v[i] * a;
55	    w += a;
56	  }
57	  if (w <= 0) return [...(BAND_STYLE[course.stageAtS(s).id] ?? BAND_DEFAULT)];
58	  return [o[0] / w, o[1] / w, o[2] / w, o[3] / w];
59	}
60	
61	/**
62	 * 05 current: lateral position (units, ribbon `right` axis, + = right) of the centre of the
63	 * electric-cyan core relative to the route centreline. The core swings WITH the course meander,
64	 * amplified by CORE_SWING, so the two pink bands trace S-bends ≈(1 + CORE_SWING)× as strong as the
65	 * route's own (ref 05: ±60–120 px). Bounded by CORE_SWING · max|offset05| (≈0.9 · 1.85 = 1.7 u at the
66	 * far crest; ≤1.25 u within 35 u of the 05 checkpoint), inside the ≥2 u core half width, so a coin on
67	 * the route centre (lat 0) still sits on cyan. 0 outside 05.
68	 * gameplay/coins.ts may place the 05 coins at this lateral to put them exactly on the core centre.
69	 */
70	export const CORE_SWING = 0.9;
71	export function coreLateral(course: Course, s: number): number {
72	  const st = course.stage('05');
73	  if (s <= st.s0 || s >= st.s1) return 0;
74	  return CORE_SWING * course.offset05(s) * course.sample(s).right.x;
75	}
76	
77	/**
78	 * Ribbon colours in shader (pre-tonemap, linear) space. NeutralToneMapping desaturates anything
79	 * whose peak channel passes ≈0.76·exposure, so these were solved by inverting Neutral at the game's
80	 * exposure 0.86 (src/render/env.ts). Flat values after tone mapping: cyanDeep #0065D6, cyan #1D89F0,
81	 * cyanBright #42C8F7, pinkDeep #E206BE, pink #F741DD (H 308°, not violet), pinkLight #FA93E7. The
82	 * streaks/crests/glints added on top lift the rendered cyan median to ≈#06A7FF (ref 05 #039FF6).
83	 * Crests/highlights are allowed to desaturate toward white (that is how the ref highlights look).
84	 * The shared PALETTE in glsl.ts is untouched (whirlpool, drum and final wave use it).
85	 */
86	const lin = (r: number, g: number, b: number) => new THREE.Color().setRGB(r, g, b, THREE.LinearSRGBColorSpace);
87	const RIBBON_PAL = {
88	  cyanDeep: lin(0.0, 0.15, 0.78),
89	  cyan: lin(0.0, 0.31, 1.12),
90	  cyanBright: lin(0.04, 0.95, 1.55),
91	  pinkDeep: lin(0.9, 0.02, 0.62),
92	  pink: lin(1.55, 0.03, 1.2),
93	  pinkLight: lin(2.2, 0.5, 1.8),
94	};
95	
96	export function ampAt(course: Course, s: number): number {
97	  let v = 0, w = 0;
98	  for (const st of course.stages) {
99	    const a = smooth(st.s0 - 5, st.s0 + 5, s) * (1 - smooth(st.s1 - 5, st.s1 + 5, s));
100	    if (a > 0) { v += (AMP[st.id] ?? 0.08) * a; w += a; }
101	  }
102	  let amp = w > 0 ? v / w : 0.08;
103	  // calm the long straight of the deep plunge (fast sheet flow)
104	  const pt = course.marks['07_plunge_top'], pb = course.marks['07_plunge_bottom'];
105	  if (pt !== undefined) amp *= 1 - 0.6 * smooth(pt, pt + 8, s) * (1 - smooth(pb - 8, pb, s));
106	  return amp;
107	}
108	
109	function smooth(a: number, b: number, x: number) {
110	  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
111	  return t * t * (3 - 2 * t);
112	}
113	
114	/** CPU mirror of the vertex displacement (keep in sync with VERT). */
115	export function ribbonWave(u: number, s: number, t: number, amp: number): number {
116	  const au = Math.min(1, Math.abs(u));
117	  const trough = EDGE_LIFT * au * au * au;
118	  return trough + amp * (0.6 * Math.sin(s * 0.9 - t * 2.4 + u * 1.7) + 0.4 * Math.sin(s * 0.41 + t * 1.5 - u * 2.3));
119	}
120	
121	const VERT = /* glsl */ `
122	attribute vec2 aUV;      // x = u (-1..1 across), y = s (arc length)
123	attribute float aHalfW;
124	attribute float aSpeed;
125	attribute float aAmp;
126	attribute float aSkirt;  // 0 surface, 1 skirt bottom
127	attribute vec4 aStyle;   // band layout: gate, offset, half width, free-meander weight (see BAND_STYLE)
128	attribute float aCore;   // 05: core-centre lateral swing (units, see coreLateral)
129	attribute vec3 aTan;     // course tangent (downstream)
130	uniform float uTime;
131	uniform vec4 uHide;      // s03Start, s04Start, chuteMark, unused
132	varying vec2 vUV;
133	varying float vHalfW;
134	varying float vSpeed;
135	varying float vSkirt;
136	varying float vHide;
137	varying vec4 vStyle;
138	varying float vCore;
139	varying vec3 vTanW;
140	varying vec3 vPosW;
141	varying vec3 vNormalW;
142	#include <fog_pars_vertex>
143	void main() {
144	  vStyle = aStyle;
145	  vCore = aCore;
146	  vTanW = normalize(mat3(modelMatrix) * aTan);
147	  float u = aUV.x;
148	  float s = aUV.y;
149	  float h = aAmp * (0.6 * sin(s * 0.9 - uTime * 2.4 + u * 1.7) + 0.4 * sin(s * 0.41 + uTime * 1.5 - u * 2.3));
150	  vec3 p = position + normal * h * (1.0 - aSkirt);
151	  vec4 wp = modelMatrix * vec4(p, 1.0);
152	  vPosW = wp.xyz;
153	  vNormalW = normalize(mat3(modelMatrix) * normal);
154	  vUV = aUV;
155	  vHalfW = aHalfW;
156	  vSpeed = aSpeed;
157	  vSkirt = aSkirt;
158	  // hand the stream over to the whirlpool surface during 03 (dithered fade both ways)
159	  float inside03 = smoothstep(uHide.x + 0.5, uHide.x + 3.5, s) * (1.0 - smoothstep(uHide.y - 9.0, uHide.y - 1.5, s));
160	  vHide = 1.0 - inside03;
161	  vec4 mvPosition = viewMatrix * wp;
162	  gl_Position = projectionMatrix * mvPosition;
163	  #include <fog_vertex>
164	}
165	`;
166	
167	const FRAG = /* glsl */ `
168	uniform float uTime;
169	uniform vec3 uCyanDeep;
170	uniform vec3 uCyan;
171	uniform vec3 uCyanBright;
172	uniform vec3 uPinkDeep;
173	uniform vec3 uPink;
174	uniform vec3 uPinkLight;
175	uniform vec3 uFoam;
176	uniform vec3 uFoamLav;
177	uniform vec3 uHaze;
178	uniform vec3 uLightDir;
179	uniform vec3 uBenny;      // s, lateral (units), strength
180	uniform float uBennyR;    // Benny's waterline radius (units)
181	uniform vec3 uChevron;    // start s, spacing, enabled
182	uniform vec2 uOutro;      // amount, chamber start s
183	varying vec2 vUV;
184	varying float vHalfW;
185	varying float vSpeed;
186	varying float vSkirt;
187	varying float vHide;
188	varying vec4 vStyle;
189	varying float vCore;
190	varying vec3 vTanW;
191	varying vec3 vPosW;
192	varying vec3 vNormalW;
193	#include <fog_pars_fragment>
194	${NOISE_GLSL}
195	${FRAG_FX_GLSL}
196	
197	// Stationary channel shape (refs 05–07): lateral offset (units) of the electric-cyan core centre
198	// relative to the course centreline. Two incommensurate sines + slow noise so the S-curves do not
199	// visibly repeat; λ≈26 u differs from the course's own 05 geometry meander (λ≈36 u), so the two beat
200	// rather than cancel. It only drifts slowly downstream (+s) at a constant rate (no shear between
201	// stage speeds); the strand texture below is what is advected at the local stage speed.
202	float meander(float s, float hw) {
203	  float a = s - uTime * 0.7;
204	  float m = 0.2 * sin(a * 0.24) + 0.08 * sin(a * 0.53 + 1.3) + 0.12 * (vnoise(vec2(a * 0.05, 4.7)) - 0.5);
205	  return m * min(hw, 4.5);
206	}
207	
208	// Combed flow lines (ref 05: thin bright streaks along the flow, 2–4 px apart in the mid-ground).
209	// Anti-aliased lines across the flow (K slots per unit), each broken into tapered streak segments of
210	// varying length/brightness. Line width is in PIXELS (≈1.2 px core + ≈2.5 px glow), so near the camera
211	// the slots spread apart into sparse crisp glints instead of wide parallel light stripes (the
212	// "flattened stripes" the user rejected); the lines fade once they get closer than ≈3 px.
213	float combed(float x, float v, float K, float seed) {
214	  float p = x * K;
215	  float id = floor(p);
216	  float fw = max(fwidth(p), 1e-4);            // slots per pixel
217	  float hs = hash12(vec2(id, seed));
218	  float dpx = abs(fract(p) - 0.5 - (hs - 0.5) * 0.5) / fw;   // pixels from the line centre
219	  float line = (1.0 - smoothstep(0.4, 1.3, dpx)) * 0.8 + exp(-dpx * 0.45) * 0.3;
220	  // each line breaks into tapered streak segments; sparser when the slots are far apart on screen
221	  float sparse = smoothstep(0.03, 0.006, fw);
222	  float seg = smoothstep(0.5 + 0.15 * sparse, 0.9, vnoise(vec2(id * 3.7 + seed, v * 0.2 + hs * 9.0)));
223	  return line * seg * (0.45 + 0.55 * hs) * (1.0 - smoothstep(0.22, 0.4, fw));
224	}
225	
226	// advected strand texture ("combed" glossy water lines parallel to the flow)
227	// x = lateral units relative to the meander centre, v = advected arc length, aa = 0..1 detail fade
228	// returns: x = height 0..1 (shading + bump), y = white glint lines, z = mid strands, w = fine strands
229	// sw = swirl (05): the strands wander laterally and are less stretched, so the water reads as
230	// curling glossy flow instead of uniform straight parallel stripes (the user's rejected look)
231	vec4 strands(float x, float v, vec2 aa, float sw) {
232	  x += sw * 0.9 * (vnoise(vec2(x * 0.45, v * 0.2 + 7.0)) - 0.5);
233	  float a = vnoise(vec2(x * 2.4, v * (0.08 + 0.1 * sw)));
234	  float b = vnoise(vec2(x * 7.0 + a * 1.6, v * 0.19 + 5.0));
235	  #ifdef LOW_Q
236	  float c = b;
237	  #else
238	  float c = vnoise(vec2(x * 17.0 + b * 2.2, v * 0.42 + 3.0));
239	  #endif
240	  b = mix(0.5, b, aa.x);
241	  c = mix(0.5, c, aa.y);
242	  float h = a * 0.42 + b * 0.34 + c * 0.24;
243	  h = smoothstep(0.18, 0.82, h);              // more contrast: deep azure troughs, bright crests
244	  float line = smoothstep(0.72, 0.86, c) * aa.y + smoothstep(0.7, 0.86, b) * aa.x * 0.85;
245	  // the combed lines follow the large-scale strand warp so they bend with the flow
246	  float xw = x + (a - 0.5) * 0.5;
247	  line = max(line, combed(xw, v, 6.0, 0.0) * 0.85);
248	  #ifndef LOW_Q
249	  line = max(line, combed(xw + (b - 0.5) * 0.12, v * 1.3, 15.0, 11.0) * 0.55);
250	  #endif
251	  return vec4(h, line, b, c);
252	}
253	
254	void main() {
255	  float u = vUV.x;
256	  float s = vUV.y;
257	  // dithered hide (03 hand-over)
258	  if (vHide < 0.5) discard;
259	  float cutFoam = 1.0 - smoothstep(0.5, 0.85, vHide);
260	  // 11 outro: the stream drains away in the chamber, leaving puddles
261	  if (uOutro.x > 0.0 && s > uOutro.y - 2.0) {
262	    float n = vnoise(vec2(u * 3.0, s * 0.35)) * 0.7 + 0.3;
263	    if (n < uOutro.x * 1.15) discard;
264	  }
265	
266	  // ---- channel layout: winding cyan core between two hot-pink S-bands, cyan again outside ----
267	  float hw = vHalfW;
268	  float lat = u * hw;                         // lateral units in the ribbon frame
269	  // core centre: free drifting meander on 04/06/07 (freeK = 1); on 05 (freeK = 0) pinned to the
270	  // course's own S-meander, amplified (vCore = CORE_SWING · offset05), so the coins stay on cyan
271	  float freeK = vStyle.w;
272	  float M = meander(s, hw) * freeK + vCore;
273	  float x = lat - M;                          // lateral units in the core's frame
274	
275	  // detail fade with distance (cells per pixel), keeps far water from shimmering
276	  float fwx = fwidth(x);
277	  float fws = fwidth(s);
278	  // (a noise cell must stay ≳6–8 px wide; the combed lines of ref 05 are 2–4 px apart in the
279	  // mid-ground, so fading earlier than this flattens the water into a plain fill)
280	  vec2 aa = vec2(1.0 - smoothstep(0.12, 0.26, max(fwx * 7.0, fws * 0.19)),
281	                 1.0 - smoothstep(0.09, 0.2, max(fwx * 17.0, fws * 0.42)));
282	  // hair-fine combed strands for close-up water (refs: dense parallel flow lines)
283	  float aaH = 1.0 - smoothstep(0.14, 0.3, fwx * 46.0);
284	  #ifdef LOW_Q
285	  aa.y = 0.0;
286	  aaH = 0.0;
287	  #endif
288	
289	  // two-phase flow-map advection of the strands (period 4 s; offset scales with stage speed)
290	  float ph0 = fract(uTime * 0.25);
291	  float ph1 = fract(uTime * 0.25 + 0.5);
292	  float w0 = 1.0 - abs(1.0 - 2.0 * ph0);
293	  float sw = 1.0 - freeK;
294	  vec4 F = mix(strands(x, s - vSpeed * ph1 * 4.0 + 23.0, aa, sw), strands(x, s - vSpeed * ph0 * 4.0, aa, sw), w0);
295	
296	  // Benny parts the bands like a bow wave (vStyle.x, ref 05): just ahead of him they narrow and
297	  // swing outward, so the water at and behind him (the near field) is pure cyan; behind him they
298	  // continue only as thin streaks pushed out toward the foam banks
299	  // (05: the near rows only show lat ±2.3 behind Benny, so a light parting is enough there)
300	  float gate = 1.0, part = 0.0;
301	  if (vStyle.x > 0.0) {
302	    float db = s - uBenny.x;
303	    // 05: half width at Benny, full width ≈20 u ahead (ref 05 bands widen into the mid/far field)
304	    float g05 = 0.5 + 0.5 * smoothstep(1.0, 20.0, db);
305	    float gOld = 0.4 + 0.6 * smoothstep(0.0, 4.5, db);
306	    gate = mix(1.0, mix(g05, gOld, freeK), vStyle.x);
307	    part = vStyle.x * hw * mix(0.1, 0.3, freeK) * (1.0 - smoothstep(-1.0, 9.0, db));
308	  }
309	  float hwc = min(hw, 4.5);
310	  float aaw = fwidth(lat) * 0.85 + 0.01;      // ≈1 px edges: no lavender cyan/pink blend zone
311	  // flowing band edges (the advected strand texture). 05: only a soft ripple, so the band edges are
312	  // clean S-curves instead of the torn/jagged combed edges of the old slab
313	  float pert = mix((F.z - 0.5) * 0.22, (F.z - 0.5) * 0.5 + (F.w - 0.5) * 0.22, freeK) * hwc * 0.22;
314	  // 05: the band shapes are carried downstream (a slow travelling wobble), so the pink S-sections
315	  // visibly flow and swirl even though the channel itself is fixed to the course meander
316	  float tv = s - uTime * vSpeed * 0.3;
317	  float wob = (1.0 - freeK) * hwc;
318	  float offL = hw * (vStyle.y + mix(0.03, 0.07, freeK) * sin(s * 0.13 + 1.7)) + part + wob * 0.05 * sin(tv * 0.42 + 1.1);
319	  float offR = hw * (vStyle.y + mix(0.03, 0.07, freeK) * sin(s * 0.11 + 4.2)) + part + wob * 0.05 * sin(tv * 0.37 + 3.9);
320	  float modA = mix(0.15, 0.4, freeK);         // 05: even band width (the ±40 % swell drew the slab)
321	  float wL = hw * vStyle.z * (1.0 + modA * sin(s * 0.19 + 0.4) + 0.08 * wob * sin(tv * 0.6)) * gate;
322	  float wR = hw * vStyle.z * (1.0 + modA * sin(s * 0.17 + 2.9) + 0.08 * wob * sin(tv * 0.55 + 2.0)) * gate;
323	  if (freeK < 0.5) {
324	    // keep both bands inside the water (the core swing pushes one toward the bank on each bend)
325	    offL = min(offL, M + hw - wL - 0.5);
326	    offR = min(offR, hw - wR - 0.5 - M);
327	  }
328	  float sdL = x + offL + pert;
329	  float sdR = x - offR + pert;
330	  float dL = abs(sdL);
331	  float dR = abs(sdR);
332	  float on = smoothstep(0.02, 0.2, gate);
333	  float pL = (1.0 - smoothstep(wL - aaw, wL + aaw, dL)) * on;
334	  float pR = (1.0 - smoothstep(wR - aaw, wR + aaw, dR)) * on;
335	  // a thin cyan thread splits a band into two streaks along some stretches (ref 05 mid-ground)
336	  float rimW = 0.05 * hwc + aaw;
337	  float thrW = 0.028 * hwc;
338	  float splitOn = smoothstep(0.55, 0.7, vnoise(vec2(s * 0.07, 13.0)));
339	  float sL = (1.0 - smoothstep(thrW, thrW + aaw, abs(x + offL + pert * 1.4 + 0.25 * wL * sin(s * 0.5)))) * splitOn;
340	  float sR = (1.0 - smoothstep(thrW, thrW + aaw, abs(x - offR + pert * 1.4 - 0.25 * wR * sin(s * 0.45 + 1.0)))) * (1.0 - splitOn);
341	  // only split bands that are wide enough (smooth ramp: a hard step cut the band across the flow)
342	  pL *= 1.0 - sL * smoothstep(rimW * 1.8, rimW * 2.8, wL);
343	  pR *= 1.0 - sR * smoothstep(rimW * 1.8, rimW * 2.8, wR);
344	  // hair-thin pink filaments drifting through the cyan core (mid/far field only)
345	  float fil = 0.0;
346	  #ifndef LOW_Q
347	  float fc = hw * 0.18 * sin(s * 0.21 + 0.8);
348	  fil = (1.0 - smoothstep(0.025 * hwc, 0.025 * hwc + aaw, abs(x - fc + pert * 0.7)))
349	      * smoothstep(0.62, 0.78, vnoise(vec2(s * 0.09, 21.0))) * gate * aa.x * freeK;   // 05 core: pure cyan
350	  #endif
351	  float pinkM = max(max(pL, pR), fil);
352	  // glossy rims: light-pink just inside each band edge, bright cyan just outside it
353	  float rimIn = max(pL * smoothstep(wL - rimW, wL - aaw, dL), pR * smoothstep(wR - rimW, wR - aaw, dR));
354	  float rimOut = max((1.0 - pL) * (1.0 - smoothstep(wL + aaw, wL + rimW * 1.6, dL)),
355	                     (1.0 - pR) * (1.0 - smoothstep(wR + aaw, wR + rimW * 1.6, dR))) * on;
356	
357	  float h = F.x;
358	  float hair = 0.5;
359	  if (aaH > 0.0) {
360	    float sv = s - vSpeed * fract(uTime * 0.5) * 2.0;
361	    float hA = vnoise(vec2(x * 46.0 + F.w * 3.0, sv * 0.9));
362	    float hB = vnoise(vec2(x * 46.0 + F.w * 3.0, (sv + vSpeed) * 0.9 + 17.0));
363	    hair = mix(0.5, mix(hB, hA, 1.0 - abs(1.0 - 2.0 * fract(uTime * 0.5))), aaH);
364	  }
365	  // deep azure troughs → electric cyan → light-cyan crests (crests stay a minority of the area)
366	  // (05: deeper base, fewer light-cyan crests; ref 05 near rows median #028BE7–#0198F0, the light
367	  // comes from crisp streaks/glints on top, not from a pale wash)
368	  vec3 cyanCol = mix(uCyanDeep, uCyan, smoothstep(mix(0.3, 0.22, freeK), mix(0.72, 0.62, freeK), h));
369	  cyanCol = mix(cyanCol, uCyanBright, smoothstep(mix(0.7, 0.64, freeK), 0.95, h) * mix(0.55, 0.7, freeK) + rimOut * 0.45);
370	  // satin ribbon: a soft light streak runs along each band, off-centre toward the core
371	  float rel = pL >= pR ? sdL / max(wL, 1e-3) : -sdR / max(wR, 1e-3);   // -1 outer edge .. +1 core side
372	  float satin = exp(-pow((rel - 0.3) * 2.2, 2.0));
373	  vec3 pinkCol = mix(uPinkDeep, uPink, smoothstep(0.3, 0.72, h + satin * 0.2));
374	  pinkCol = mix(pinkCol, uPinkLight, clamp(smoothstep(0.6, 0.92, h) * 0.7 + satin * 0.35 + rimIn * 0.45, 0.0, 1.0));
375	  vec3 col = mix(cyanCol, pinkCol, pinkM);
376	  col *= 0.88 + 0.24 * hair;
377	  vec3 streakCol = mix(vec3(0.6, 1.25, 1.6), vec3(1.6, 0.8, 1.6), pinkM);
378	  col += streakCol * smoothstep(0.82, 0.94, hair) * 0.3 * aaH;
379	
380	  // ---- glossy lighting ----
381	  vec3 N0 = normalize(vNormalW);
382	  if (!gl_FrontFacing) N0 = -N0;
383	  #ifdef LOW_Q
384	  vec3 N = normalize(N0 + 0.25 * vec3(h - 0.5, 0.0, F.z - 0.5));
385	  #else
386	  float bumpAmt = 0.07 * (1.0 - smoothstep(0.1, 0.5, fws));
387	  vec3 N = bumpNormal(vPosW, N0, h * bumpAmt);
388	  #endif
389	  vec3 V = normalize(cameraPosition - vPosW);
390	  float nv = clamp(dot(N, V), 0.0, 1.0);
391	  float fres = pow(1.0 - nv, 4.0);
392	  vec3 R = reflect(-V, N);
393	  // tinted (not white) reflection so the glossy far water stays saturated, not pastel
394	  vec3 reflTint = mix(uCyanBright, uPinkLight, pinkM);
395	  vec3 refl = mix(reflTint, vec3(1.5), smoothstep(0.6, 1.0, R.y) * 0.5);
396	  col = mix(col, refl, fres * 0.22);
397	  vec3 L = normalize(uLightDir);
398	  vec3 H = normalize(L + V);
399	  float spec = pow(clamp(dot(N, H), 0.0, 1.0), 120.0);
400	  float sheen = pow(clamp(dot(R, L), 0.0, 1.0), 10.0);
401	  col += vec3(1.0) * spec * 1.2 + reflTint * sheen * 0.12;
402	  // glossy white-blue reflection of the bright tunnel end (refs 05–07): the light sits far
403	  // downstream, so its mirror image is a glitter path along the river toward the VP, broken into
404	  // streaks by the bump normals and the strand crests (never a flat milky sheet)
405	  vec3 Lg = normalize(vTanW + N0 * 0.1);
406	  float glit = pow(clamp(dot(R, Lg), 0.0, 1.0), 160.0);
407	  float glitMask = smoothstep(0.5, 0.88, h) * 0.75 + F.y * 0.6;
408	  col += mix(vec3(0.7, 1.1, 1.45), vec3(1.5, 0.85, 1.4), pinkM) * glit * glitMask * mix(0.9, 0.45, freeK);
409	  // advected glossy streak lines along the flow
410	  col += streakCol * F.y * 0.8;
411	
412	  // ---- foreground ripple crests (ref 05 near field: thin arcs of white crest light over deep-azure
413	  // troughs, drifting downstream). Pixel-thin lines bowed upstream around the core, in short
414	  // segments, so the near water reads as moving glossy ripples, not soft horizontal bars.
415	  float nearK = 1.0 - smoothstep(0.02, 0.05, fws);
416	  if (nearK > 0.0) {
417	    float ph = s * 4.2 - uTime * 6.0 + 0.2 * x * x + 1.6 * vnoise(vec2(lat * 0.7, s * 0.45));
418	    float q = fract(ph * 0.159155 - 0.25) - 0.5;              // 0 on a crest (sin = 1)
419	    float dpx = abs(q) / max(fwidth(ph * 0.159155), 1e-4);
420	    float crest = (1.0 - smoothstep(0.5, 1.8, dpx)) * smoothstep(0.52, 0.8, vnoise(vec2(lat * 2.6, s * 1.1 + 3.0)));
421	    col *= 1.0 - 0.14 * nearK * (0.5 - 0.5 * sin(ph));
422	    col += mix(vec3(0.9, 1.4, 1.7), vec3(1.7, 1.1, 1.7), pinkM) * crest * nearK * mix(0.9, 0.6, freeK);
423	  }
424	
425	  // ---- white star glints (4-point, twinkling, carried by the flow) ----
426	  #ifdef LOW_Q
427	  vec2 g = vec2(lat * 1.2, (s - vSpeed * uTime * 0.6) * 0.8);
428	  float hs = hash12(floor(g));
429	  float sparkle = step(0.9, hs) * smoothstep(0.22, 0.0, length(fract(g) - 0.5)) * (0.5 + 0.5 * sin(uTime * 7.0 + hs * 40.0));
430	  col += vec3(1.3) * sparkle;
431	  #else
432	  // wide cells so the long horizontal arms are not clipped at the cell border in the mid-ground
433	  float glint = starGlint(vec2(lat * 0.55, (s - vSpeed * uTime * 0.55) * 0.42), 0.42, 22.0, 2.4, uTime);
434	  col += vec3(2.0, 2.2, 2.3) * glint * (1.0 - smoothstep(0.3, 0.8, fws));
435	  // finer star layer for the near/mid water (ref 05: dozens of small white 4-point flares on the
436	  // cyan around and behind Benny); 05 only (freeK = 0) so 04/06/07 keep their look
437	  if (freeK < 0.99) {
438	    float glint2 = starGlint(vec2(x * 1.5, (s - vSpeed * uTime * 0.55) * 1.2), 0.3, 13.0, 2.2, uTime + 2.7);
439	    col += vec3(1.9, 2.1, 2.3) * glint2 * (1.0 - smoothstep(0.08, 0.3, fws)) * (1.0 - 0.6 * pinkM) * (1.0 - freeK);
440	  }
441	  #endif
442	
443	  // ---- soap-foam lace where the water meets the foam banks ----
444	  float edgeN = (vnoise(vec2(s * 1.3, u * 2.0)) - 0.5) * 0.1;
445	  float eu = abs(lat) - vHalfW;               // units from the edge (negative inside)
446	  float edge = smoothstep(-0.75, -0.3, eu + edgeN * vHalfW);
447	  if (edge > 0.0) {
448	    float c = cells(vec2(lat * 3.2, (s - vSpeed * uTime * 0.35) * 3.2));
449	    vec3 foamCol = mix(uFoam * 1.15, uFoamLav * 0.85, smoothstep(0.25, 0.75, c));
450	    col = mix(col, foamCol, edge * smoothstep(0.05, 0.4, c + edge * 0.3));
451	  }
452	  col = mix(col, uFoamLav * 0.92, vSkirt);
453	  float cutC = cells(vec2(u * vHalfW * 4.0, s * 3.6));
454	  col = mix(col, mix(uFoam * 1.2, uFoamLav * 0.8, smoothstep(0.2, 0.7, cutC)), cutFoam);
455	
456	  // ---- Benny: ripple rings and a V wake on the surface ----
457	  // (the 3D splash crown, spray fan and foam belong to riderSplash/spray/foam; here the water
458	  // around and behind him stays glossy electric cyan as in ref 05.) There is deliberately NO white
459	  // contact band at the waterline: the old contact -> uFoam mix drew a white elliptical rim that the
460	  // fur fringe turned into the jagged "splash artifact" under Benny (wave-3 correction 7). Only a
461	  // faint cyan brightening marks the waterline.
462	  if (uBenny.z > 0.0) {
463	    float du = lat - uBenny.y;
464	    float dv = s - uBenny.x;
465	    float rb = uBennyR;
466	    float d = length(vec2(du, dv));
467	    if (d < rb * 8.0) {
468	      float k = uBenny.z;
469	      float rr = max(0.0, d - rb * 0.92);
470	      float rings = smoothstep(0.75, 1.0, 0.5 + 0.5 * sin(d * 5.0 - uTime * 9.0)) * exp(-rr * 0.55) * smoothstep(rb, rb * 1.3, d);
471	      float back = max(-dv, 0.0);
472	      float wakeV = exp(-abs(abs(du) - back * 0.42 - rb * 0.95) * 6.0) * exp(-back * 0.18) * step(dv, 0.0);
473	      col += uCyanBright * 0.18 * (1.0 - smoothstep(0.0, rb * 0.3, rr)) * k;
474	      col += mix(uCyanBright, vec3(1.3), 0.4) * (rings * 0.22 + wakeV * 0.35) * k * (1.0 - pinkM * 0.5);
475	    }
476	  }
477	
478	  // 04: exactly five glowing chevrons pointing downhill (direction of travel)
479	  if (uChevron.z > 0.5) {
480	    float x = u * vHalfW;
481	    for (int k = 0; k < 5; k++) {
482	      float y = s - (uChevron.x + float(k) * uChevron.y);
483	      if (abs(y) < 2.4 && abs(x) < 1.6) {
484	        // "^" pointing toward +s: tip at y=+1.0, arms sweep back 1.9 units over ±1.15 lateral
485	        float dist = abs(y - (1.0 - abs(x) * 1.65)) * 0.52;
486	        float arm = smoothstep(1.2, 1.1, abs(x));
487	        float core = smoothstep(0.2, 0.11, dist) * arm;
488	        float halo = smoothstep(0.7, 0.0, dist) * smoothstep(1.5, 0.9, abs(x)) * 0.5;
489	        col = mix(col, vec3(1.0), clamp(halo, 0.0, 1.0));
490	        col = mix(col, vec3(2.2, 2.4, 2.5), core);
491	      }
492	    }
493	  }
494	  gl_FragColor = vec4(col, 1.0);
495	  ${FRAG_TAIL}
496	}
497	`;
