499	export interface Ribbon {
500	  mesh: THREE.Mesh;
501	  uniforms: Record<string, THREE.IUniform>;
502	  s0: number;
503	  s1: number;
504	  heightAt(s: number, lateral: number, t: number): number;
505	}
506	
507	export function createRibbon(course: Course, opts: { s0: number; s1: number; quality: 'high' | 'low' }): Ribbon {
508	  const { s0, s1, quality } = opts;
509	  const ds = quality === 'high' ? 0.4 : 0.7;
510	  const cols = quality === 'high' ? 18 : 10;
511	  const rows = Math.ceil((s1 - s0) / ds) + 1;
512	  const vertsPerRow = cols + 1 + 2; // + skirt left/right
513	  const n = rows * vertsPerRow;
514	  const pos = new Float32Array(n * 3);
515	  const nor = new Float32Array(n * 3);
516	  const uv = new Float32Array(n * 2);
517	  const halfW = new Float32Array(n);
518	  const speed = new Float32Array(n);
519	  const amp = new Float32Array(n);
520	  const skirt = new Float32Array(n);
521	  const style = new Float32Array(n * 4);
522	  const core = new Float32Array(n);
523	  const tang = new Float32Array(n * 3);
524	  const tmp = new THREE.Vector3();
525	  const nrm = new THREE.Vector3();
526	  let k = 0;
527	  for (let i = 0; i < rows; i++) {
528	    const s = Math.min(s1, s0 + i * ds);
529	    const f = course.sample(s);
530	    const hw = course.widthAt(s) / 2;
531	    const sp = Math.max(3, course.prop(s, 'speed'));
532	    const a = ampAt(course, s);
533	    const bs = bandStyleAt(course, s);
534	    const cl = coreLateral(course, s);
535	    const put = (u: number, lateral: number, h: number, isSkirt: number, nn: THREE.Vector3) => {
536	      tmp.copy(f.pos).addScaledVector(f.right, lateral).addScaledVector(f.up, h);
537	      tmp.toArray(pos, k * 3);
538	      nn.toArray(nor, k * 3);
539	      f.tan.toArray(tang, k * 3);
540	      uv[k * 2] = u;
541	      uv[k * 2 + 1] = s;
542	      halfW[k] = hw;
543	      speed[k] = sp;
544	      amp[k] = a;
545	      skirt[k] = isSkirt;
546	      for (let q = 0; q < 4; q++) style[k * 4 + q] = bs[q];
547	      core[k] = cl;
548	      k++;
549	    };
550	    // left skirt (below left edge)
551	    put(-1, -hw * 1.01, EDGE_LIFT - 0.7, 1, nrm.copy(f.right).negate());
552	    for (let j = 0; j <= cols; j++) {
553	      const u = -1 + (2 * j) / cols;
554	      const lift = EDGE_LIFT * Math.abs(u) ** 3;
555	      const slope = (EDGE_LIFT * 3 * u * Math.abs(u)) / hw; // d lift / d lateral
556	      nrm.copy(f.up).addScaledVector(f.right, -slope).normalize();
557	      put(u, u * hw, lift, 0, nrm);
558	    }
559	    put(1, hw * 1.01, EDGE_LIFT - 0.7, 1, nrm.copy(f.right));
560	  }
561	  const idx: number[] = [];
562	  for (let i = 0; i < rows - 1; i++) {
563	    for (let j = 0; j < vertsPerRow - 1; j++) {
564	      const a = i * vertsPerRow + j, b = a + 1, c = a + vertsPerRow, d = c + 1;
565	      idx.push(a, c, b, b, c, d);
566	    }
567	  }
568	  const geo = new THREE.BufferGeometry();
569	  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
570	  geo.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
571	  geo.setAttribute('aUV', new THREE.BufferAttribute(uv, 2));
572	  geo.setAttribute('aHalfW', new THREE.BufferAttribute(halfW, 1));
573	  geo.setAttribute('aSpeed', new THREE.BufferAttribute(speed, 1));
574	  geo.setAttribute('aAmp', new THREE.BufferAttribute(amp, 1));
575	  geo.setAttribute('aSkirt', new THREE.BufferAttribute(skirt, 1));
576	  geo.setAttribute('aStyle', new THREE.BufferAttribute(style, 4));
577	  geo.setAttribute('aCore', new THREE.BufferAttribute(core, 1));
578	  geo.setAttribute('aTan', new THREE.BufferAttribute(tang, 3));
579	  geo.setIndex(idx);
580	  geo.computeBoundingSphere();
581	
582	  const st03 = course.stage('03'), st04 = course.stage('04'), st08 = course.stage('08');
583	  const uniforms = withFog({
584	    uTime: { value: 0 },
585	    uCyanDeep: { value: RIBBON_PAL.cyanDeep.clone() },
586	    uCyan: { value: RIBBON_PAL.cyan.clone() },
587	    uCyanBright: { value: RIBBON_PAL.cyanBright.clone() },
588	    uPinkDeep: { value: RIBBON_PAL.pinkDeep.clone() },
589	    uPink: { value: RIBBON_PAL.pink.clone() },
590	    uPinkLight: { value: RIBBON_PAL.pinkLight.clone() },
591	    uFoam: { value: PALETTE.foam.clone() },
592	    uFoamLav: { value: PALETTE.foamLav.clone() },
593	    uHaze: { value: PALETTE.haze.clone() },
594	    uLightDir: { value: new THREE.Vector3(0.3, 1.0, 0.45).normalize() },
595	    uBenny: { value: new THREE.Vector3(0, 0, 0) },
596	    uBennyR: { value: 0.7 },
597	    uChevron: { value: new THREE.Vector3(st04.s0 + 8.5, 3.6, 1) },
598	    uOutro: { value: new THREE.Vector2(0, st08.s0) },
599	    uHide: { value: new THREE.Vector4(st03.s0, st04.s0, 0, 0) },
600	  });
601	  const mat = new THREE.ShaderMaterial({
602	    uniforms,
603	    vertexShader: VERT,
604	    fragmentShader: FRAG,
605	    fog: true,
606	    side: THREE.DoubleSide,
607	    defines: quality === 'low' ? { LOW_Q: 1 } : {},
608	  });
609	  const mesh = new THREE.Mesh(geo, mat);
610	  mesh.name = 'water_ribbon';
611	  mesh.frustumCulled = false; // one long mesh spanning the whole course
612	  return {
613	    mesh,
614	    uniforms,
615	    s0,
616	    s1,
617	    heightAt(s, lateral, t) {
618	      const hw = course.widthAt(s) / 2;
619	      return ribbonWave(lateral / hw, s, t, ampAt(course, s));
620	    },
621	  };
622	}
