1	/** Shared GLSL snippets for Rainbow water/foam/bubble shaders (WebGL2, mobile-safe). */
2	import * as THREE from 'three';
3	
4	export const NOISE_GLSL = /* glsl */ `
5	float hash12(vec2 p) {
6	  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
7	  p3 += dot(p3, p3.yzx + 33.33);
8	  return fract((p3.x + p3.y) * p3.z);
9	}
10	float vnoise(vec2 p) {
11	  vec2 i = floor(p);
12	  vec2 f = fract(p);
13	  vec2 u = f * f * (3.0 - 2.0 * f);
14	  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
15	             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
16	}
17	float fbm3(vec2 p) {
18	  float a = 0.5, s = 0.0;
19	  for (int i = 0; i < 3; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }
20	  return s;
21	}
22	// cheap cellular "soap foam" pattern: 0 at cell centres -> 1 at borders
23	float cells(vec2 p) {
24	  vec2 i = floor(p);
25	  vec2 f = fract(p);
26	  float md = 8.0;
27	  for (int y = -1; y <= 1; y++) for (int x = -1; x <= 1; x++) {
28	    vec2 g = vec2(float(x), float(y));
29	    vec2 o = vec2(hash12(i + g), hash12(i + g + 19.7));
30	    vec2 r = g + o - f;
31	    md = min(md, dot(r, r));
32	  }
33	  return sqrt(md);
34	}
35	vec3 iridescent(float t) {
36	  return 0.5 + 0.5 * cos(6.28318 * (t + vec3(0.0, 0.33, 0.67)));
37	}
38	`;
39	
40	/**
41	 * Fragment-only helpers (use screen-space derivatives, so never include in a vertex shader).
42	 *  - bumpNormal: Mikkelsen-style "bump mapping without tangents" from a scalar height field
43	 *  - starGlint:  4-point star glint anchored to a world-space cell grid but sized in PIXELS, so the
44	 *                cross stays star-shaped under grazing foreshortening (refs 05–07 white glints)
45	 */
46	export const FRAG_FX_GLSL = /* glsl */ `
47	vec3 bumpNormal(vec3 pos, vec3 n, float h) {
48	  vec3 dpx = dFdx(pos);
49	  vec3 dpy = dFdy(pos);
50	  float dhx = dFdx(h);
51	  float dhy = dFdy(h);
52	  vec3 r1 = cross(dpy, n);
53	  vec3 r2 = cross(n, dpx);
54	  float det = dot(dpx, r1);
55	  vec3 grad = sign(det) * (dhx * r1 + dhy * r2);
56	  return normalize(abs(det) * n - grad);
57	}
58	// g: cell coordinates (world-anchored); density: probability a cell holds a star; L: arm length px;
59	// stretch: horizontal (g.x) arm length relative to the vertical one (ref 05 glints are wide flares)
60	float starGlint(vec2 g, float density, float L, float stretch, float time) {
61	  vec2 gi = floor(g);
62	  float hs = hash12(gi + 7.31);
63	  if (hs < 1.0 - density) return 0.0;
64	  vec2 cpp = max(fwidth(g), vec2(1e-4));           // cells per pixel
65	  vec2 c = vec2(hash12(gi + 3.1), hash12(gi + 5.7)) * 0.5 + 0.25;
66	  vec2 px = (fract(g) - c) / cpp;                   // offset in pixels
67	  vec2 lim = 0.24 / cpp;                            // never cross the cell border
68	  float l = L * (0.55 + 0.9 * fract(hs * 37.0));
69	  float ax = exp(-abs(px.y) * 0.75) * max(0.0, 1.0 - abs(px.x) / min(l * stretch, lim.x));
70	  float ay = exp(-abs(px.x) * 0.8) * max(0.0, 1.0 - abs(px.y) / min(l, lim.y));
71	  float core = exp(-dot(px, px) * 0.05) * 1.6;
72	  float tw = 0.55 + 0.45 * pow(0.5 + 0.5 * sin(time * 5.0 + hs * 60.0), 2.0);
73	  return ((ax * ax + ay * ay) * 1.6 + core) * tw;
74	}
75	`;
