77	/**
78	 * Rainbow water palette (sRGB hex → linear THREE.Color, ready for uniforms).
79	 * Base hues are scaled below the NeutralToneMapping knee (~0.76 linear) so the renderer does not
80	 * desaturate them toward pastel; only highlights/sparkles/foam exceed 1.0 (and feed bloom).
81	 */
82	const knee = (hex: string, k = 0.74) => new THREE.Color(hex).multiplyScalar(k);
83	export const PALETTE = {
84	  cyanDeep: knee('#0a62f0', 0.72),
85	  cyan: knee('#08c0ff'),
86	  cyanBright: knee('#56f0ff', 0.8),
87	  pink: knee('#ff149f'),
88	  pinkLight: knee('#ff4cc0', 0.78),
89	  magenta: new THREE.Color('#e01ea0'),
90	  foam: new THREE.Color('#ffffff'),
91	  foamLav: new THREE.Color('#efe2ff'),
92	  haze: new THREE.Color('#ffd6f4'),
93	};
94	
95	/** fog-aware uniforms merged into every water ShaderMaterial */
96	export function withFog<T extends Record<string, THREE.IUniform>>(u: T): T & typeof THREE.UniformsLib.fog {
97	  return THREE.UniformsUtils.merge([THREE.UniformsLib.fog, u]) as T & typeof THREE.UniformsLib.fog;
98	}
99	
100	/** standard tail: tonemapping + colour space + fog (call with gl_FragColor already set) */
101	export const FRAG_TAIL = /* glsl */ `
102	  #include <tonemapping_fragment>
103	  #include <colorspace_fragment>
104	  #include <fog_fragment>
105	`;
