// Map screen pixels of the 05 checkpoint to ribbon (s, lateral) via the game's own probe() raycast.
// run with cwd = project root: node <this>
import { loadPlaywright, CHROMIUM_ARGS, startVite } from '/home/user/rainbow-/scripts/lib/pw.mjs';
const { chromium } = loadPlaywright();
const vite = await startVite(5231);
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  await page.goto(`${vite.url}/?qa=1&dpr=1`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 240000 });
  const cp = await page.evaluate(() => window.__rainbow.goto('05'));
  console.log('checkpoint', JSON.stringify(cp), JSON.stringify(await page.evaluate(() => window.__rainbow.state())));
  const res = await page.evaluate(() => {
    const R = window.__rainbow, c = R.course;
    const st = R.state();
    const s0 = st.s;
    const locate = (p) => {
      let best = 1e9, bs = 0;
      for (let s = s0 - 15; s < s0 + 140; s += 0.05) {
        const f = c.sample(s);
        const dx = p[0] - f.pos.x, dy = p[1] - f.pos.y, dz = p[2] - f.pos.z;
        const along = dx * f.tan.x + dy * f.tan.y + dz * f.tan.z;
        if (Math.abs(along) < best) { best = Math.abs(along); bs = s; }
      }
      const f = c.sample(bs);
      const lat = (p[0] - f.pos.x) * f.right.x + (p[1] - f.pos.y) * f.right.y + (p[2] - f.pos.z) * f.right.z;
      return { s: +bs.toFixed(2), lat: +lat.toFixed(2), hw: +(c.widthAt(bs) / 2).toFixed(2), core: +(0.9 * c.offset05(bs) * f.right.x).toFixed(2) };
    };
    const rows = [520, 560, 600, 650, 700, 750, 800, 900, 1000, 1100, 1200, 1300, 1400, 1500, 1530];
    const xs = [10, 100, 200, 300, 432, 560, 660, 760, 854];
    const out = [];
    for (const y of rows) {
      const line = [];
      for (const x of xs) {
        const nx = (x + 0.5) / 864 * 2 - 1, ny = -((y + 0.5) / 1536 * 2 - 1);
        const hits = R.probe(nx, ny);
        const w = hits.find((h) => h.obj.startsWith('water_ribbon'));
        if (!w) { line.push(`${x}:${hits[0] ? hits[0].obj.split('<')[0].slice(0, 10) : '-'}`); continue; }
        const L = locate(w.p);
        line.push(`${x}:s${L.s}/l${L.lat}(hw${L.hw},c${L.core})`);
      }
      out.push(`y${y}  ` + line.join('  '));
    }
    return out.join('\n');
  });
  console.log(res);
} finally {
  await browser.close();
  await vite.close();
}

