"""Forward model of the Rainbow post chain (no bloom, no vignette):
linear HDR -> exposure 0.86 -> Khronos Neutral -> sRGB -> grade (sat 1.36, contrast 1.15).
python3 -I tonemodel.py r g b [r g b ...]   prints the display hex for each linear triple
python3 -I tonemodel.py solve #HEX          searches a linear triple that lands on the hex"""
import sys, itertools


def neutral(c, exp=0.86):
    c = [v * exp for v in c]
    x = min(c)
    off = x - 6.25 * x * x if x < 0.08 else 0.04
    c = [v - off for v in c]
    peak = max(c)
    sc = 0.8 - 0.04
    if peak < sc:
        return c
    d = 1 - sc
    np_ = 1 - d * d / (peak + d - sc)
    c = [v * np_ / peak for v in c]
    g = 1 - 1 / (0.15 * (peak - np_) + 1)
    return [v * (1 - g) + np_ * g for v in c]


def srgb(v):
    v = max(0.0, min(1.0, v))
    return 12.92 * v if v <= 0.0031308 else 1.055 * v ** (1 / 2.4) - 0.055


def grade(c, sat=1.36, con=1.15):
    l = 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]
    c = [l + (v - l) * sat for v in c]
    return [max(0, min(1, (v - 0.5) * con + 0.5)) for v in c]


def disp(lin):
    return grade([srgb(v) for v in neutral(lin)])


def hx(c):
    return '#%02X%02X%02X' % tuple(round(v * 255) for v in c)


if __name__ == '__main__':
    a = sys.argv[1:]
    if a and a[0] == 'solve':
        t = a[1].lstrip('#'); T = [int(t[i:i + 2], 16) / 255 for i in (0, 2, 4)]
        best = None
        grid = [i / 40 for i in range(0, 121)]
        for r in grid:
            for g in grid:
                for b in grid:
                    d = disp([r, g, b]); e = sum((d[i] - T[i]) ** 2 for i in range(3))
                    if best is None or e < best[0]: best = (e, (r, g, b), d)
        print('target', a[1], 'lin', best[1], '->', hx(best[2]), 'err', round(best[0] ** 0.5 * 255, 1))
    else:
        v = list(map(float, a))
        for i in range(0, len(v), 3):
            print(v[i:i + 3], '->', hx(disp(v[i:i + 3])))

