  const dA = WORLD.drumA;
  const hc = V(0, -0.4, 0); // swirl axis
  const th0 = Math.atan2(-2.0, 1.6);
  push(V(1.6, -2.4, -2.2));
  mark('01');
  // ---- 02: whirlpool tumble — helix around the drum axis toward the back drain ----
  const thEnd = -Math.PI / 2 - Math.PI * 2;
